      "evidence_id": "A0",
      "span": "In this paper, a supervised learning technique for extracting keyphrases of Arabic documents is presented.",
      "roles": ["method", "contribution"],
      "origin": "current"
    },
    {
      "evidence_id": "A1",
      "span": "The extractor is supplied with linguistic knowledge to enhance its efficiency instead of relying only on statistical information such as term frequency and distance.",
      "roles": ["method"],
      "origin": "current"
